"""Golden AuthZEN requests: loading and comparison.

Golden files come from three places:

* ``golden/requests/`` (generated by ``scripts/gen_golden.py`` from the
  spec's conformance cases);
* ``golden/<tes>/``: requests a TES recorded in its own hook tests (e.g.
  ``golden/poiesis/``), every subdirectory of ``golden/`` except
  ``requests/`` and ``hook/``;
* every directory in ``TES_AUTHZ_GOLDEN_DIRS`` (``:``-separated), for
  recordings kept outside this repository; they add to the others. A
  directory that does not exist is an error, as is one that
  contains, or lies inside, a directory already read (e.g. ``golden/``
  itself). Files under hidden directories are skipped.

A golden file is either a wrapper ``{"name", "case", "description",
"request", "expect": {"<policy>": {"decision": bool}}}`` or a bare AuthZEN
request. Bare requests (and wrappers without an expectation for a policy)
get expectations from ``golden/expectations.json``
(``{"<label>/<file stem>": {"<policy>": {"decision": bool}}}``, where
the label is the directory relative to the repository root, e.g.
``golden/poiesis``, or its absolute path without the leading ``/`` for a
directory outside it); without one,
``test_every_golden_case_has_an_expectation`` fails. Two files with the
same name are an error, as is a non-boolean ``decision``.
"""

from __future__ import annotations

import copy
import json
import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

SERVICE_ROOT = Path(__file__).resolve().parent.parent
GOLDEN_ROOT = SERVICE_ROOT / "golden"
LOCAL_DIR = GOLDEN_ROOT / "requests"
EXPECTATIONS = GOLDEN_ROOT / "expectations.json"
NOT_RECORDINGS = frozenset({"requests", "hook"})
"""Subdirectories of ``golden/`` that hold no TES recordings."""

MASK = "<masked>"


@dataclass
class GoldenCase:
    """One golden request with its expectations.

    Attributes:
        name: Unique name (file stem, prefixed with the source for shared files).
        path: The file.
        request: The AuthZEN request.
        expect: Expected decisions per policy name.
        case: Spec conformance case number(s), if known.
        description: What the case shows.
    """

    name: str
    path: Path
    request: dict[str, Any]
    expect: dict[str, bool] = field(default_factory=dict)
    case: str = ""
    description: str = ""


def golden_dirs() -> list[Path]:
    """Return the directories to read golden files from.

    Returns:
        Existing directories without duplicates: the generated requests,
        then the TES recordings in ``golden/<tes>/``, then the directories
        in ``TES_AUTHZ_GOLDEN_DIRS``.

    Raises:
        ValueError: A directory in ``TES_AUTHZ_GOLDEN_DIRS`` does not exist,
            or a directory contains, or lies inside, a directory that is
            read already, so its cases would be read twice.
    """
    excluded = {(GOLDEN_ROOT / name).resolve() for name in NOT_RECORDINGS}
    entries = GOLDEN_ROOT.iterdir() if GOLDEN_ROOT.is_dir() else iter(())
    recordings = sorted(d for d in entries if d.is_dir() and not d.name.startswith(".") and d.resolve() not in excluded)
    extra = os.environ.get("TES_AUTHZ_GOLDEN_DIRS", "")
    candidates = [LOCAL_DIR, *recordings]
    for directory in (Path(part) for part in extra.split(":") if part):
        if not directory.is_dir():
            msg = f"TES_AUTHZ_GOLDEN_DIRS: no directory {directory}"
            raise ValueError(msg)
        candidates.append(directory)
    dirs: list[Path] = []
    seen: set[Path] = set()
    for directory in candidates:
        if not directory.is_dir():
            continue
        resolved = directory.resolve()
        if resolved in seen:
            continue
        overlap = sorted(str(d) for d in seen if d.is_relative_to(resolved) or resolved.is_relative_to(d))
        if overlap:
            msg = f"golden directory {directory} overlaps {', '.join(overlap)}, which is read already"
            raise ValueError(msg)
        seen.add(resolved)
        dirs.append(directory)
    return dirs


def _label(directory: Path) -> str:
    """Name a golden directory uniquely.

    Args:
        directory: The directory.

    Returns:
        Its path relative to the repository root, or its absolute path
        without the leading ``/`` for a directory outside the repository.
    """
    try:
        return str(directory.resolve().relative_to(SERVICE_ROOT.resolve()))
    except ValueError:
        return str(directory.resolve()).lstrip("/")


def _expectations() -> dict[str, dict[str, Any]]:
    if EXPECTATIONS.exists():
        data: dict[str, dict[str, Any]] = json.loads(EXPECTATIONS.read_text())
        return data
    return {}


def load_cases() -> list[GoldenCase]:
    """Load every golden request.

    Returns:
        The cases, sorted by name.
    """
    sidecar = _expectations()
    found: dict[str, GoldenCase] = {}
    for directory in golden_dirs():
        prefix = "" if directory == LOCAL_DIR else f"{_label(directory)}/"
        for path in sorted(directory.rglob("*.json")):
            if any(part.startswith(".") for part in path.relative_to(directory).parts):
                continue
            data = json.loads(path.read_text())
            if not isinstance(data, dict):
                continue
            stem = prefix + str(path.relative_to(directory).with_suffix(""))
            if "request" in data:
                request = data["request"]
                expect_raw = dict(data.get("expect", {}))
            elif "subject" in data and "action" in data and "resource" in data:
                request, expect_raw = data, {}
            else:
                continue
            for policy, value in sidecar.get(stem, {}).items():
                expect_raw.setdefault(policy, value)
            expect = {}
            for policy, value in expect_raw.items():
                if not isinstance(value, dict) or not isinstance(value.get("decision"), bool):
                    raise ValueError(f"{path}: expectation for {policy!r} needs a boolean 'decision'")
                expect[policy] = value["decision"]
            if stem in found:
                raise ValueError(f"duplicate golden case {stem!r}: {found[stem].path} and {path}")
            found[stem] = GoldenCase(
                stem, path, request, expect, str(data.get("case", "")), str(data.get("description", ""))
            )
    return [found[name] for name in sorted(found)]


def instantiate(golden: dict[str, Any], fixtures: dict[str, Any]) -> dict[str, Any]:
    """Fill the per-TES placeholders of a golden request.

    A string that is exactly ``{{name}}`` becomes ``fixtures[name]`` (e.g.
    the owner ID, which differs per TES), so one golden file fits every
    TES. A placeholder whose fixture value is ``None`` removes its key
    (spec section 3.7: subject keys without a value are left out). A
    placeholder without a fixture value stays as it is and shows up in the
    diff.

    Args:
        golden: The golden request.
        fixtures: Placeholder name to the TES-specific value.

    Returns:
        A filled deep copy.
    """

    def walk(node: Any) -> Any:
        if isinstance(node, dict):
            return {key: walk(value) for key, value in node.items() if not _absent(value, fixtures)}
        if isinstance(node, list):
            return [walk(value) for value in node]
        if isinstance(node, str) and node.startswith("{{") and node.endswith("}}"):
            return fixtures.get(node[2:-2], node)
        return node

    result: dict[str, Any] = walk(copy.deepcopy(golden))
    return result


def _absent(node: Any, fixtures: dict[str, Any]) -> bool:
    """Whether a node is a placeholder whose fixture value is ``None``.

    Args:
        node: A golden value.
        fixtures: Placeholder name to the TES-specific value.

    Returns:
        ``True`` if the key holding this node is to be left out.
    """
    if not (isinstance(node, str) and node.startswith("{{") and node.endswith("}}")):
        return False
    name = node[2:-2]
    return name in fixtures and fixtures[name] is None


def diff(expected: Any, actual: Any, path: str = "$") -> list[str]:
    """List the differences between two JSON values.

    Args:
        expected: The golden value.
        actual: The recorded (normalised) value.
        path: JSON path prefix for messages.

    Returns:
        Human-readable differences; empty when equal.
    """
    if isinstance(expected, dict) and isinstance(actual, dict):
        out: list[str] = []
        for key in sorted(set(expected) | set(actual)):
            if key not in actual:
                out.append(f"{path}.{key}: missing")
            elif key not in expected:
                out.append(f"{path}.{key}: unexpected {actual[key]!r}")
            else:
                out += diff(expected[key], actual[key], f"{path}.{key}")
        return out
    if isinstance(expected, list) and isinstance(actual, list):
        if len(expected) != len(actual):
            return [f"{path}: length {len(actual)} != {len(expected)}"]
        return [d for i, (e, a) in enumerate(zip(expected, actual, strict=True)) for d in diff(e, a, f"{path}[{i}]")]
    if expected == MASK:
        return []
    return [] if expected == actual else [f"{path}: {actual!r} != {expected!r}"]
